import com.cowave.search.application.index.dto.LinkedProductRequest
import com.cowave.search.application.index.dto.UnlinkedProductDeleteRequest
import com.cowave.search.application.index.dto.UnlinkedProductRequest
import com.cowave.search.application.index.repository.LegacySyncRepository
import com.cowave.search.client.legacy_api.LegacyApiClient
import com.cowave.search.domain.index.enums.Operation
import com.cowave.shared.utils.logger
import org.springframework.http.HttpMethod
import org.springframework.stereotype.Component

@Component
class LegacySyncRepositoryImpl(
    private val legacyApiClient: LegacyApiClient,
) : LegacySyncRepository {
    private val logger by logger()

    override suspend fun pushLinkedProducts(
        products: List<LinkedProductRequest>,
        operation: Operation,
    ) {
        logger.info { "레거시 연동상품 동기화 요청 [operation=$operation, count=${products.size}]" }
        legacyApiClient.pushQueue(service = "PDM", method = operation.toHttpMethod(), body = products)
    }

    override suspend fun pushUnlinkedProducts(
        products: List<UnlinkedProductRequest>,
        operation: Operation,
    ) {
        logger.info { "레거시 비연동상품 동기화 요청 [operation=$operation, count=${products.size}]" }
        legacyApiClient.pushQueue(service = "TCMPNY_LINK", method = operation.toHttpMethod(), body = products)
    }

    override suspend fun pushUnlinkedProductDeletes(products: List<UnlinkedProductDeleteRequest>) {
        logger.info { "레거시 비연동상품 삭제 동기화 요청 [count=${products.size}]" }
        legacyApiClient.pushQueue(service = "TCMPNY_LINK", method = HttpMethod.DELETE, body = products)
    }

    private fun Operation.toHttpMethod(): HttpMethod =
        when (this) {
            Operation.CREATE -> HttpMethod.POST
            Operation.UPDATE -> HttpMethod.PUT
            Operation.DELETE -> HttpMethod.DELETE
        }
}"}

{"result":"package com.cowave.search.outbound_adapter.legacy

import com.cowave.search.application.index.dto.LinkedProductRequest
import com.cowave.search.application.index.dto.UnlinkedProductDeleteRequest
import com.cowave.search.application.index.dto.UnlinkedProductRequest
import com.cowave.search.client.legacy_api.LegacyApiClient
import com.cowave.search.domain.index.enums.Operation
import io.kotest.core.spec.style.FunSpec
import io.kotest.matchers.shouldBe
import io.mockk.coEvery
import io.mockk.coVerify
import io.mockk.mockk
import io.mockk.slot
import org.springframework.http.HttpMethod

class LegacySyncRepositoryImplTest : FunSpec({

    val legacyApiClient = mockk<LegacyApiClient>()
    val repository = LegacySyncRepositoryImpl(legacyApiClient)

    beforeEach {
        coEvery { legacyApiClient.pushQueue(any(), any(), any()) } returns Unit
    }

    context("pushLinkedProducts") {
        val products = listOf(
            LinkedProductRequest(shopProductCode = "P001", shopCode = "S001"),
        )

        test("CREATE 연동상품 동기화 - POST로 호출한다") {
            val serviceSlot = slot<String>()
            val methodSlot = slot<HttpMethod>()

            coEvery {
                legacyApiClient.pushQueue(capture(serviceSlot), capture(methodSlot), any())
            } returns Unit

            repository.pushLinkedProducts(products, Operation.CREATE)

            serviceSlot.captured shouldBe "PDM"
            methodSlot.captured shouldBe HttpMethod.POST
            coVerify(exactly = 1) { legacyApiClient.pushQueue("PDM", HttpMethod.POST, products) }
        }

        test("UPDATE 연동상품 동기화 - PUT으로 호출한다") {
            val methodSlot = slot<HttpMethod>()

            coEvery {
                legacyApiClient.pushQueue(any(), capture(methodSlot), any())
            } returns Unit

            repository.pushLinkedProducts(products, Operation.UPDATE)

            methodSlot.captured shouldBe HttpMethod.PUT
            coVerify(exactly = 1) { legacyApiClient.pushQueue("PDM", HttpMethod.PUT, products) }
        }

        test("DELETE 연동상품 동기화 - DELETE로 호출한다") {
            val methodSlot = slot<HttpMethod>()

            coEvery {
                legacyApiClient.pushQueue(any(), capture(methodSlot), any())
            } returns Unit

            repository.pushLinkedProducts(products, Operation.DELETE)

            methodSlot.captured shouldBe HttpMethod.DELETE
            coVerify(exactly = 1) { legacyApiClient.pushQueue("PDM", HttpMethod.DELETE, products) }
        }
    }

    context("pushUnlinkedProducts") {
        // TODO(human): 비연동상품 테스트 데이터와 3가지 Operation 테스트 케이스를 구현하세요
    }

    context("pushUnlinkedProductDeletes") {
        val products = listOf(
            UnlinkedProductDeleteRequest(shopCode = "S001", shopProductCode = "P001"),
        )

        test("비연동상품 삭제 동기화 - DELETE로 호출한다") {
            val serviceSlot = slot<String>()
            val methodSlot = slot<HttpMethod>()

            coEvery {
                legacyApiClient.pushQueue(capture(serviceSlot), capture(methodSlot), any())
            } returns Unit

            repository.pushUnlinkedProductDeletes(products)

            serviceSlot.captured shouldBe "TCMPNY_LINK"
            methodSlot.captured shouldBe HttpMethod.DELETE
            coVerify(exactly = 1) {
                legacyApiClient.pushQueue("TCMPNY_LINK", HttpMethod.DELETE, products)
            }
        }
    }
})"}
